        bit_depth: Annotated[int | None, WithJsonSchema({'default': 8, 'description': '目标色深（也称为位深），仅专业版（tool_version 为 professional）支持。取值如下：8：（默认值）8 bit 位深，每个颜色通道有 2⁸（即 256）个亮度等级。支持 h264、h265 编码。10：10 bit 位深，每个颜色通道有 2¹⁰（即 1024）个亮度等级。支持 h265、prores 编码。12：12 bit 位深，每个颜色通道有 2¹²（即 4096）个亮度等级。支持 h265 编码。16：16 bit 位深，每个颜色通道有 2¹⁶（即 65536）个亮度等级。支持 ffv1、exr 编码。注意：请确保输入视频时长不超过 40 秒。此档位下，码率由系统自动决定，bitrate、bitrate_level 参数均不生效。16 bit 色深任务为单任务串行处理，即只能单一任务处理完成后，再开始新任务处理，因此处理时间可能较长。', 'enum': [8, 10, 12, 16], 'type': 'integer'})] = Field(None, json_schema_extra={'default': 8}),
