        scale_short: Annotated[int | None, WithJsonSchema({'description': 'scale_short 最小值为 0，最大值为 4096。输出图片短边不得超过原始视频短边。按短边缩放时，输出图片长边按原始比例自适应。enable_sprite 为 true 时，scale_short 定义单张小图的短边。同时设置 scale_long 和 scale_short 时保持原始宽高比，并分别约束长边和短边。', 'maximum': 4096, 'minimum': 0, 'type': 'integer', 'x-description-en': "The maximum pixel value for the output image's short side. It can be set from a minimum of 0 to a maximum of 4096, and the output image's short side cannot exceed the original video's short side. When enable_sprite is true, this value defines the short side of a single tile."})] = Field(None),
